from itertools import combinations, permutations
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
n=14
edges=[(i,j) for i in range(n) for j in range(i+1,n)]
eid={e:k+1 for k,e in enumerate(edges)}
# generate simple cycles length 3..6 unique as sets of edge vars
cycles=set(); cyc_lists=[]
def canon(cyc):
    # cyc vertices ordered around cycle length k, canonical rotation/reversal
    k=len(cyc)
    seqs=[]
    for s in (cyc, list(reversed(cyc))):
        for r in range(k):
            seqs.append(tuple(s[r:]+s[:r]))
    return min(seqs)
for k in range(3,7):
    for verts in combinations(range(n), k):
        # enumerate Hamilton cycles on this vertex set fixing first min and second choices? easier all perms unique
        vs=list(verts)
        first=vs[0]
        for perm in permutations(vs[1:]):
            cyc=[first]+list(perm)
            # avoid reversal duplicates: require cyc[1] < cyc[-1]
            if cyc[1] > cyc[-1]: continue
            c=canon(cyc)
            if c in cycles: continue
            cycles.add(c)
            vars=[]
            ok=True
            for a,b in zip(cyc,cyc[1:]+cyc[:1]):
                if a>b: a,b=b,a
                vars.append(eid[(a,b)])
            cyc_lists.append(vars)
print('cycles', len(cyc_lists), {k:sum(1 for c in cyc_lists if len(c)==k) for k in range(3,7)})

vpool=IDPool(start_from=len(edges)+1)
solver=Glucose3()
# no short cycles: at least one edge absent per cycle
for vars in cyc_lists:
    solver.add_clause([-x for x in vars])
# at least 19 edges
cnf=CardEnc.atleast(lits=list(range(1,len(edges)+1)), bound=19, vpool=vpool, encoding=EncType.seqcounter)
for cl in cnf.clauses: solver.add_clause(cl)
# 4-coloring vars maybe only enforce if edge exists? Let's include
color_var={}
for v in range(n):
    for c in range(4):
        color_var[(v,c)] = vpool.id(('color',v,c))
    solver.add_clause([color_var[(v,c)] for c in range(4)])
    for c1 in range(4):
        for c2 in range(c1+1,4):
            solver.add_clause([-color_var[(v,c1)], -color_var[(v,c2)]])
for (u,v),x in eid.items():
    for c in range(4):
        solver.add_clause([-x, -color_var[(u,c)], -color_var[(v,c)]])
print('vars', vpool.top, 'clauses', solver.nof_clauses())
sat=solver.solve()
print('sat',sat)
if sat:
    m=solver.get_model(); S=set(i for i in m if i>0)
    sol=[e for e,x in eid.items() if x in S]
    print('edges',len(sol),sol)
    # colors
    cols=[]
    for v in range(n):
        for c in range(4):
            if color_var[(v,c)] in S: cols.append(c)
    print('colors',cols)
solver.delete()
